// Moves every cloud name of an import/export from the engine's main entry into a /cloud one.
import { readFileSync, writeFileSync } from 'node:fs';
import { execSync } from 'node:child_process';
const MAIN = '@wolsok/feat-shared-bacteria-engine';
const cloud = new Set(readFileSync(process.argv[2], 'utf8').trim().split('\n'));
const files = execSync(`grep -rlE "from '${MAIN}'" apps libs tools --include=*.ts --include=*.mts`).toString().trim().split('\n').filter(f => !f.startsWith('libs/features/bacteria-engine/'));
const re = new RegExp(`(import|export)( type)? \\{([^}]*)\\} from '${MAIN.replace(/\//g, '\\/')}';`, 'g');
let changed = 0;
for (const f of files) {
  const src = readFileSync(f, 'utf8');
  const out = src.replace(re, (all, kw, typeKw, body) => {
    const specs = body.split(',').map(s => s.trim()).filter(Boolean);
    const name = s => s.replace(/^type /, '').split(/\s+as\s+/)[0].trim();
    const c = specs.filter(s => cloud.has(name(s))), r = specs.filter(s => !cloud.has(name(s)));
    if (!c.length) return all;
    const stmt = (list, mod) => `${kw}${typeKw ?? ''} { ${list.join(', ')} } from '${mod}';`;
    return [r.length ? stmt(r, MAIN) : null, stmt(c, MAIN + '/cloud')].filter(Boolean).join('\n');
  });
  if (out !== src) { writeFileSync(f, out); changed++; console.log(f); }
}
console.error(changed + ' files');
EOF
